import re
for f in ["transformation-patterns.md","optimization.md","validation-and-enforcement.md","workflow-examples.md"]:
    print("=====",f)
    lines=open(f).read().splitlines()
    state=None; flen=0; fchar=None; start=0
    for i,l in enumerate(lines,1):
        m=re.match(r'^(\s*)(`{3,}|~{3,})(.*)$', l)
        if state is None:
            if m:
                state=m.group(2); fchar=m.group(2)[0]; flen=len(m.group(2)); start=i
                print("OPEN",i,repr(l), "len",flen)
        else:
            if m and m.group(2)[0]==fchar and len(m.group(2))>=flen and m.group(3).strip()=="":
                print("CLOSE",i,repr(l),"from",start)
                state=None
    if state: print("UNCLOSED from",start)
